{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret bruger ikke vejledningens kriterium (art og grad ikke tilstrækkeligt beskrevet). Det erstatter de fire eksempler med egne, bl.a. 'mulighed for at arbejde ved siden af studiet', og siger at myndigheden 'bør kunne forklare'. Det hævder også, at Udbetaling Danmark normalt ikke er myndigheden, og at ansøger kan skulle betale. Det er i strid med kilderne, hvor Udbetaling Danmark anmoder og betaler."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element er kun delvist med: 'ikke tilstrækkelige til at afgøre sagen' er mere generelt end 'art og grad ikke tilstrækkeligt beskrevet'. 'I særlige tilfælde' mangler. De fire eksempelgrupper mangler næsten helt: symptomintensitet/-hyppighed, diskrepans, behandling/prognose og dagligdag versus ferie. Der er kun løse paralleller om varighed og funktionsevne."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret behandler spørgsmålet om, hvornår en speciallægeerklæring kan bestilles, men svarer med generiske betingelser i stedet for vejledningens udløsere. Det bruger plads på at omdefinere myndigheden og på praktiske råd om betaling og skriftlighed. Dermed er de væsentlige dele af spørgsmålet ikke besvaret."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ingen kilde at vurdere."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen kilde at vurdere støtte mod."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer regler uden støtte i materialet. Uddannelses- og Forskningsstyrelsen er angivet som normal myndighed i stedet for Udbetaling Danmark. Eksempler om arbejde ved siden af studiet er opfundet. Det hævder, at myndigheden 'bør' forklare, hvad der mangler. Det antyder, at ansøger kan skulle betale, og at manglende medvirken kan føre til afgørelse på det foreliggende grundlag og afslag. Ingen af delene har støtte i de udleverede kilder."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Det centrale forbehold 'i særlige tilfælde' er ikke gengivet. Svaret siger kun, at ikke alle ansøgere skal have en erklæring. Eksemplerne gengives ikke som illustrative alternativer, og 'stor tvivl' er ikke bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: erklæring kan bestilles ved utilstrækkelige oplysninger, og det er ikke et krav i alle sager. Konklusionen følger af svarets egne trin, selv om præmisserne er juridisk forkerte."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'bør' om myndighedens forklaringspligt og 'kan' om afslag, uden at kilden støtter det. Det gengiver ikke vejledningens 'i særlige tilfælde' og 'anmoder, hvis'. Det flytter også betalingen i retning af ansøger i stedet for den kildebaserede regel om, at Udbetaling Danmark betaler."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret siger, at en speciallægeerklæring kan indhentes, når oplysningerne ikke er tilstrækkelige. Det mangler 'i særlige tilfælde', art og grad af funktionsnedsættelsen og alle fire konkrete eksempler, og det forkert identificerer myndigheden."
    }
  },
  "overall_notes": "Svaret er generelt og uden kildehenvisninger. Det rammer kun den overordnede idé om utilstrækkelig dokumentation og siger, at erklæring ikke kræves i alle sager. Det udelader vejledningens fire eksempler og forbeholdet 'i særlige tilfælde', og det tilføjer ustøttede påstande om myndighed, betaling og afslag."
}

